method.description:
[b]Required for a custom layout.[/b] Mirrors Android's [b]LayoutManager.onLayoutChildren[/b]: lay out every item visible at the current scroll offset and recycle the ones that left the viewport. Typical steps:

[codeblock]
func _on_layout_children(recycler_view, state) -> void:
    var offset: int = recycler_view.get_scroll_offset()
    var viewport: Vector2 = recycler_view.get_viewport_size()
    var extent: int = recycler_view.get_item_extent(0)
    var first := maxi(0, offset / extent)
    var last := mini(get_item_count() - 1, (offset + int(viewport.y)) / extent)

    # 1. Recycle holders that left the viewport.
    for i in range(recycler_view.get_child_holder_count() - 1, -1, -1):
        var holder = recycler_view.get_child_holder_at(i)
        if holder.get_position() < first or holder.get_position() > last:
            recycler_view.remove_item_view(holder)
            recycler_view.recycle_view(holder, holder.get_position())

    # 2. Fill the visible range (skip positions already in the tree).
    for pos in range(first, last + 1):
        var holder = _existing(recycler_view, pos)  # scan get_child_holder_at()
        if holder == null:
            holder = recycler_view.get_view_for_position(pos)  # obtain + bind
            recycler_view.add_item_view(holder)
        recycler_view.set_item_view_position(holder, Vector2(0, pos * extent - offset), Vector2(viewport.x, extent))
[/codeblock]

A script subclass that does not override it prints a warning and lays out nothing.
